import React from 'react'

function Input({ type, placeholder, value, onChange, name, className, readOnly, ...rest }) {
  return (
    <input type={type} placeholder={placeholder} value={value} onChange={onChange} name={name} className={className} readOnly={readOnly} {...rest} />
  )
}

export default Input;
